import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {
  delegatingTo,
  stopEngines,
  testClients as clients,
  testServers as servers,
  deferred,
} from './wsTestSupport.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import type {SessionStore} from '../types/sessionStore.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';

describe('listing conversations over the WebSocket protocol › lock bypass', () => {
  afterEach(async () => {
    await stopEngines();
  });

  it('answers list_sessions while a user_message is streaming, without waiting for the lock', async () => {
    const inner = new InMemorySessionStore();
    const store: SessionStore = {
      ...delegatingTo(inner),
      listFor: async () => [],
    };

    const {until, release} = deferred();

    const slowOrchestrator: ChatOrchestrator = {
      processMessage: async () => 'hi',
      async *processMessageStream(): any {
        yield {type: 'text', text: 'hi'};
        await until; // Wait here
        yield {type: 'stop', stopReason: 'end_turn'};
      },
    };

    const hal = createServer({
      app: (() => undefined) as unknown as Express,
      wsAuth: async () => ({id: 'u1'}),
      sessionStore: store,
      orchestrator: slowOrchestrator,
      history: {enabled: true},
    });
    await hal.start(0);
    servers.push(hal);
    const {port} = hal.server.address() as AddressInfo;
    const url = `ws://127.0.0.1:${port}/hal/ws`;

    const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
    clients.push(client);

    const seen: string[] = [];
    const frames: any[] = [];

    await new Promise<void>((resolve, reject) => {
      const timeout = setTimeout(() => reject(new Error('Test timed out')), 5000);

      client.on('message', raw => {
        const frame = JSON.parse(String(raw));
        seen.push(frame.type);
        frames.push(frame);

        if (frame.type === 'connected') {
          client.send(JSON.stringify({type: 'user_message', content: 'hello'}));
        }

        if (frame.type === 'entry_upsert' && frame.entry.role === 'assistant') {
          // The stream has started. Now send list_sessions.
          client.send(JSON.stringify({type: 'list_sessions'}));
        }

        if (frame.type === 'session_list') {
          // We got the list! Now we can release the stream.
          release();
        }

        if (frame.type === 'stream_end') {
          clearTimeout(timeout);
          resolve();
        }
      });

      client.on('error', reject);
    });

    // Verify that session_list came BEFORE stream_end
    const listIndex = seen.indexOf('session_list');
    const streamEndIndex = seen.indexOf('stream_end');

    expect(listIndex).toBeGreaterThan(-1);
    expect(streamEndIndex).toBeGreaterThan(-1);
    expect(listIndex).toBeLessThan(streamEndIndex);
  });
});

