import {ListSessionsMessage} from '../../types/messages.js';

export interface ValidationResult {
  valid: boolean;
  error?: string;
  data?: any;
}

export function validateMessage(message: unknown): ValidationResult {
  if (typeof message !== 'object' || message === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const record = message as Record<string, unknown>;
  const {type} = record;

  if (typeof type !== 'string') {
    return {valid: false, error: 'Message must have a type string'};
  }

  switch (type) {
    case 'user_message':
      return validateUserMessage(record);
    case 'ping':
      return validatePingMessage(record);
    case 'list_sessions':
      return validateListSessionsMessage(record);
    default:
      return {valid: false, error: `Unknown message type: ${type}`};
  }
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const validated: ListSessionsMessage = {type: 'list_sessions'};

  const {limit} = message;
  if (limit !== undefined && !isValidLimit(limit)) {
    return {valid: false, error: 'list_sessions limit must be an integer between 0 and 200'};
  }
  if (limit !== undefined) {
    validated.limit = limit;
  }

  if (message.before === undefined) {
    return {valid: true, data: validated};
  }

  if (typeof message.before !== 'object' || message.before === null) {
    return {valid: false, error: 'list_sessions before must be an object'};
  }

  const before = message.before as Record<string, unknown>;
  const {sessionId, updatedAt} = before;

  if (typeof sessionId !== 'string' || sessionId.length < 1 || sessionId.length > 128) {
    return {valid: false, error: 'list_sessions before.sessionId must be 1-128 chars'};
  }
  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') {
    return {valid: false, error: 'list_sessions before.updatedAt must be a string or number'};
  }
  if (typeof updatedAt === 'number' && !Number.isFinite(updatedAt as number)) {
    return {valid: false, error: 'list_sessions before.updatedAt must be a finite number'};
  }
  if (typeof updatedAt === 'string' && isNaN(Date.parse(updatedAt))) {
    return {valid: false, error: 'list_sessions before.updatedAt must be a valid date string'};
  }

  validated.before = {
    sessionId,
    updatedAt: updatedAt as string | number,
  };

  return {valid: true, data: validated};
}

function isValidLimit(limit: unknown): limit is number {
  return typeof limit === 'number' && Number.isInteger(limit) && limit >= 0 && limit <= 200;
}

